function numberText(r){return r.type==='applyResource'&&r.mode==='multiply'?'최대치의 '+(r.value>0?'+':'')+r.value+'%':r.mode==='multiply'?'×'+r.value:(Number(r.value)>0?'+':'')+r.value;}
