    skillDrafts:[...Object.values(w.definitions.skills),...proposal.skills.filter(s=>!w.definitions.skills[s.id])],
    itemDrafts:[...Object.values(w.definitions.items),...proposal.items.filter(i=>!w.definitions.items[i.id])],
    lootDrafts:clone(w.definitions.loot),eventDrafts:Object.values(w.definitions.events),
    initialStateDraft:{actors:[],items:[],wallets:{}},assumptions:proposal.assumptions,conflicts:proposal.conflicts,
