  if(sceneBased) {
    const check=value=>{if(!value || typeof value!=='object')return;
      assert(!(value.provenance?.basis==='explicit' && value.provenance.sourceIds.includes('scene:appearance')),'SOURCE_EVIDENCE_MISMATCH','장면 설명은 추정 자료입니다. 로어의 명시적 수치로 표시하지 마세요.');
      for(const x of Object.values(value))check(x);};
    check(p);assert(!p.possessions.length,'SOURCE_EVIDENCE_MISMATCH','로어 근거 없는 새 인물에게 소지품을 자동 지급하지 않습니다.');
  }
