    const def=w.definitions.actors[plan.definitionId];
    assert(!def.summon && def.kind!=='summon','SUMMON_AUTHORITY','소환수는 소환 도구로 불러오세요.');
    const id=plan.definitionId;
    assert(!w.actors[id],'DUPLICATE_ID','현재 인물 ID가 이미 사용 중입니다.');
    actor=w.actors[id]=makeActor(def,id);
