    assert(app.settings.encounterGeneration!==false,'ACTOR_BUILD_DISABLED','AI 연결에서 등장 인물 자동 구축을 켜세요.');
    const all=await this.guard(scope,tx,w.profileRef.sourceHash),sources=selectedSources(all,args,w);
    const definitionId='cast-'+(await hash(normalize(args.name))).slice(0,24);
    const actorModel=modelFromWorld(w);
