    const fingerprint=await hash({pipeline:'semantic-actor-v3',identity:context,profile:w.profile,statContract:w.meta.statContract || null,actorModel,
      sourceHash:w.profileRef.sourceHash,connection:app.settings.connection});
    const key=(await app.repo.key(scope))+'/actor-build/'+fingerprint;
    const planFor=p=>{
      const aliases2=[...aliases,...p.identity.aliases,p.actor.name];
      const existing=findDefinition(w,{name:p.actor.name,aliases:p.identity.aliases});
      return {definitionId:existing || definitionId,aliases:aliases2,proposal:existing ? null : p};
    };
