    if(record?.status==='ready') {const plan=planFor(record.proposal);if(plan.proposal)verifyProposal(w,record.proposal,context);return plan;}
    assert(!record || record.status==='retry','ACTOR_BUILD_BLOCKED',args.name+'의 이전 구축이 '+(record?.status==='pending' ? '중단되어 결과가 불확실합니다.' : '실패했습니다: '+(record?.error?.message || '검사 실패'))+' RPG 상태 → AI 연결 → 실패한 인물 구축 다시 허용을 누른 뒤 다시 진행하세요.');
    validateConnection(app.settings.connection);
    record={name:args.name,status:'pending',requests:record?.requests || 0,proposal:record?.proposal || null,error:null};
    let prior=null,priorIntent=null,feedback=null,attempted=false;
    const outputSchema=actorSchemaFor(actorModel);
    const messages=rows=>[{role:'system',content:ACTOR},
      {role:'user',content:canonical({name:args.name,aliases:context.aliases,kind:context.kind,definitionId,sources:rows,
        actorModel,calibration:actorModel.calibration || null,
        sceneOnly:sources.some(s=>s.id==='scene:appearance'),
        priorIntent:authoringInput(priorIntent),feedback})}];
    const signatures=new Set();
