            const intent=normalizeActorIntent(mergeIntent(priorIntent,normalizeOptionalInput(parseModelJSON(response.text),actorSchema),'actor'),context);record.intent=intent;
            const next=compileActor(intent,{...context,profile:w.profile,statContract:w.meta.statContract,actorModel});record.proposal=next;
            verifyProposal(w,next,context);
            assert(!prior || prior.actor.skills.every(id=>next.actor.skills.includes(id)),'ACTOR_COVERAGE','앞서 읽은 자료에서 확인한 기술이 누락되었습니다.');
            assert(!prior || prior.possessions.every(p=>next.possessions.some(n=>n.definitionId===p.definitionId)),
              'ACTOR_COVERAGE','앞서 읽은 자료에서 확인한 소지품이 누락되었습니다.');
