  const owned=Object.values(w.inventory).filter(x=>x.ownerId===actorId&&['weapon','armor','accessory'].includes(x.type)&&x.quantity>0);
  const matches=owned.filter(x=>[x.name,x.id].some(n=>R.norm(action).includes(R.norm(n))));
  const item=matches.sort((a,b)=>b.name.length-a.name.length)[0];if(!item)return null;
  const context=action+' '+String(args.intent||''),slots={right_hand:'오른손|right.?hand',left_hand:'왼손|left.?hand',head:'머리|head',armor:'갑옷|몸통|armor',waist:'허리|waist',shoes:'신발|shoes',gloves:'장갑|gloves',accessory_1:'장신구 ?1|accessory_1',accessory_2:'장신구 ?2|accessory_2'};
