    const double=skills.find(x=>/Double Draw|더블 드로우/i.test(x.name));
    Object.assign(passive,{type:'passive',mpCost:0,cooldown:0,power:0,effects:[{type:'cooldownBypass',skill:double?.name||'더블 드로우',value:0}]});
