  if(has('accuracy'))next.target=compiled.target;
  if(has('damageType'))next.damageType=compiled.damageType;
  if(has('evasionFormula'))next.evasionFormula=compiled.evasionFormula;if(has('masteryPlan'))next.masteryPlan=compiled.masteryPlan;
