    assert(target && typeof source==='string' && source.trim() && !used.has(target),'ADAPTER_INVALID','변환할 능력치를 하나씩 지정해야 합니다.');used.add(target);
    assert(scale>0 && scale<=1000000 && Math.abs(offset)<=1000000,'ADAPTER_INVALID','능력치 변환 배율을 확인하세요.');
    return {source:source.trim(),target,scale,offset};
