    assert(JSON.stringify(answer) === JSON.stringify(fixture) || answer.ok === true && answer.nonce === fixture.nonce && answer.text === fixture.text && Object.keys(answer).length === 3, 'CONNECTION_JSON_MISMATCH', 'HTTP 응답은 왔지만 예상한 JSON 확인 값이 다릅니다.');
