  const turn = r.turn || (Array.isArray(r.order) && !r.initiativeRolls ? r : null);
  const rolledInitiative = Array.isArray(r.initiativeRolls) && r.initiativeRolls.length > 0;
  const opening = !rolledInitiative && (turn?.opening || r.opening);
