  if (!turns && !opening && turn?.turnTable!==false && (r.currentActorId || r.nextActorId)) receipts.push({ label: '다음 차례', rows: [['인물', name(r.currentActorId || r.nextActorId)], ...(Number.isFinite(r.round) ? [['라운드', r.round]] : [])] });
  if (turn?.ended || r.combatEnded || r.ended && entry.tool === 'rpg_combat') receipts.push({ label: '전투 종료', rows: [] });
  // Executed linked actions are separate saved gameplay steps. Only explain
