  if(unsafeOwnership.test(clause) || unsafeOwnership.test(paragraph.slice(Math.max(0,offset-paragraphStart-240),offset-paragraphStart+clause.length)))return false;
  if(/\b(?:who|whom|whose|which|said|says|told|reports?|believes?|claims?)\b|말했|말한|말하|전했|주장|이라고|했다고|다는/iu.test(clause))return false;
  const identity=String(intent.identity?.quote || ''),identityLabel=source.id===intent.identity?.sourceId ? String(source.label || '') : '';
  const actorNames=[intent.name,...(intent.aliases || []).filter(name=>mentions(identity+'\n'+identityLabel,name))].filter(name=>typeof name==='string' && name.trim());
  const names=actorNames.map(escapePattern).join('|'),item=escapePattern(gear.name);
  if(!names)return false;
  const owner='(?:'+names+')',verb='(?:owns?|carries|carry|wields?|wears?|holds?|possesses|possess|has|is\\s+equipped\\s+with|is\\s+carrying)';
  const determiner='\\s+(?:(?:a|an|the|her|his|their|own|one|two|three|[0-9]+)\\s+){0,3}';
  const koreanBefore='\\s*(?:(?:현재|지금|자신의|전용|개인|한|두|세|[0-9]+)\\s*){0,4}',koreanAfter='(?:을|를|은|는|이|가)?\\s*(?:(?:현재|지금|손에|양손에|늘|항상|직접|여전히)\\s*){0,4}(?:소유|소지|보유|착용|장착|쥐고|들고)';
  const namedEnglish=new RegExp('(?:^|[^\\p{L}\\p{N}])'+owner+'(?:\\s*\\([^)]{0,50}\\))?\\s+'+verb+determiner+item,'iu');
  const possessive=new RegExp('(?:^|[^\\p{L}\\p{N}])'+owner+"['’]s\\s+"+item,'iu');
  const namedKorean=new RegExp(owner+'(?:은|는|이|가|의)?'+koreanBefore+item+koreanAfter,'iu');
  const attributed=new RegExp(item+'[^.!?\\n]{0,50}(?:owned\\s+by|belongs\\s+to|소유자\\s*[:：])\\s*'+owner,'iu');
  if(namedEnglish.test(clause) || possessive.test(clause) || namedKorean.test(clause) || attributed.test(clause))return true;
  const anchor=source.id===intent.identity?.sourceId && identity ? source.content.indexOf(identity) : -1;
  const labeled=actorNames.some(name=>mentions(source.label || '',name));
