  const subjects=[...prefix.matchAll(/(?:^|[.!?\n]\s*)([A-Z][\p{L}' -]{0,35})\s+(?:is|has|owns|carries|wears|holds|wields|said|says)\b/gu)].map(m=>m[1].trim());
