  const visit=e=>{if(typeof e==='number')return;if(e.op==='stat')assert(keys.includes(e.key),'STAT_CONTRACT',label+': 없는 능력치 '+e.key,{allowed:keys});for(const arg of e.args || [])visit(arg);};
