  for(const stat of intent.stats) {
    const key=resolveKey(model.stats,stat.key,'능력치');assert(!seen.has(key),'DUPLICATE_ID','같은 능력치가 두 번 제시되었습니다: '+key);seen.add(key);
    statEvidence[key]=checkEvidence(stat.evidence,context,[stat.value],intent.name+' '+key);raw[key]=stat.value;
  }
