  if(model.legacy) notes.push('기존 시스템의 대표 인물 기준을 재사용했습니다. 새 세계관 구축에서 일반인 기준과 자원 수식을 지정할 수 있습니다.');
  const resourcesByKey=new Map();
  for(const resource of intent.resources || []) {const key=resolveKey(model.resources,resource.key,'자원');assert(!resourcesByKey.has(key),'DUPLICATE_ID','같은 자원이 두 번 제시되었습니다: '+key);resourcesByKey.set(key,resource);}
  const actor={id:definitionId,name:intent.name,kind:context.kind || intent.kind || 'ally',level:intent.level ?? 1,rank:intent.rank || '',raw,modifiers:{},resources:[],skills:[],tags:[],
    provenance:inferred(sources.map(s=>s.id),'원문에서 확인한 값과 세계관 기준의 제안값을 함께 조립한 인물입니다. 제안값: '
      +keys.filter(k=>statEvidence[k]?.basis!=='explicit').map(k=>k+'='+raw[k]).join(', '))};
  const actorForExpression={...actor,resources:{}};
  for(const modelResource of model.resources) {
    const row=resourcesByKey.get(modelResource.key) || {},claimed=[row.max,row.current].filter(Number.isFinite);
    const suppliedEvidence=checkEvidence(row.evidence,context,claimed,intent.name+' '+modelResource.name);
    let maxFormula=null,max=row.max ?? modelResource.max;
    if(modelResource.formula!==undefined) {
      maxFormula=typeof modelResource.formula==='object' ? clone(modelResource.formula) : expressionFor(modelResource.formula,keys,modelResource.name,formulaAliases);
      max=Math.max(1,Math.floor(expression(maxFormula,actorForExpression,profile)));
      if(row.max!==undefined && row.max!==max && suppliedEvidence.basis==='explicit') {max=row.max;maxFormula=null;}
    }
    assert(Number.isFinite(max) && max>=1 && max<=1000000,'INVALID_RESOURCE',modelResource.name+'의 최대값을 계산할 수 없습니다.');
    const current=Math.min(row.current ?? max,max);
    let provenance=suppliedEvidence;
    if(maxFormula) {
      const inputKeys=new Set();const scan=e=>{if(typeof e==='number')return;if(e.op==='stat')inputKeys.add(e.key);for(const arg of e.args || [])scan(arg);};scan(maxFormula);
      const formulaEvidence=checkEvidence(modelResource.evidence,context,[],modelResource.name+' 계산식');
      if(formulaEvidence.basis==='explicit' && [...inputKeys].every(k=>statEvidence[k]?.basis==='explicit') && (current===max || suppliedEvidence.basis==='explicit')) {
        provenance={...clone(formulaEvidence),basis:'derived',note:'검증한 능력치와 세계관의 자원 계산식으로 산출했습니다.',calculation:{expression:maxFormula,
          inputs:[...inputKeys].map(key=>({key,value:raw[key],sourceId:statEvidence[key].sourceIds.find(id=>sources.some(s=>s.id===id && s.content.includes(statEvidence[key].quote))),quote:statEvidence[key].quote})),
          ...(current!==max ? {current:{value:current,sourceId:suppliedEvidence.sourceIds.find(id=>sources.some(s=>s.id===id && s.content.includes(suppliedEvidence.quote))),quote:suppliedEvidence.quote}} : {})}};
      } else provenance=inferred([...suppliedEvidence.sourceIds,...(formulaEvidence?.sourceIds || [])],modelResource.name+' 최대값은 승인한 세계관 수식으로 계산했습니다. 원문에 없는 입력값은 세계관 기준으로 보완했습니다.');
    } else if(row.max===undefined || row.current===undefined) provenance=inferred(suppliedEvidence.sourceIds,'현재값 또는 최대값은 승인한 세계관 기준에서 보완했습니다. '+(suppliedEvidence.note || ''));
    const resource={id:modelResource.key,name:modelResource.name || modelResource.key,role:modelResource.role,max,current,binding:'plugin-owned',sourcePath:'',provenance,...(maxFormula ? {maxFormula} : {})};
    actor.resources.push(resource);actorForExpression.resources[resource.id]=resource;
  }
