  kind:{attack:['attack','damage','offensive','offense','공격','공격기'],heal:['heal','healing','recovery','회복','치유'],defense:['defense','defence','defensive','block','guard','방어','방어기'],evasion:['evasion','dodge','evade','회피'],utility:['utility','support','buff','debuff','유틸리티','보조','지원','강화','약화']},
  action:{action:['action','standard','standardaction','main','mainaction','normal','normalaction','fullaction','일반','일반행동','주행동','기본행동','행동'],bonus:['bonus','bonusaction','minor','minoraction','보조행동','추가행동'],reaction:['reaction','reactionaction','reactive','counter','반응','반응행동','반격'],free:['free','freeaction','noaction','자유','자유행동','행동소모없음']},
  mode:{flat:['flat','fixed','absolute','amount','고정','고정값','정액'],percentMax:['percentmax','maxpercent','percentageofmax','maxhppercent','최대비율','최대값비율'],percentCurrent:['percentcurrent','currentpercent','percentageofcurrent','현재비율','현재값비율']},
  reset:{day:['day','daily','perday','일일','하루'],long_rest:['longrest','긴휴식','장기휴식'],short_rest:['shortrest','짧은휴식','단기휴식'],scene:['scene','encounter','battle','combat','전투','장면'],never:['never','none','없음','회복없음']},
