  for(const row of [...(Array.isArray(intent?.stats)?intent.stats:[]),...(Array.isArray(intent?.resources)?intent.resources:[])])
    if(row && typeof row==='object' && row.evidence!==undefined)row.evidence=normalizeEvidenceInput(row.evidence,{sources,label:row.name || row.key});
  validate(worldSchema,intent);
  assert(intent.stats.length && intent.resources.some(r=>r.role==='vital'),'STAT_CONTRACT','세계관에 기본 능력치와 생명 자원이 필요합니다.');
