function formulaToText(e){return typeof e==='number'?String(e):e.op==='stat'?e.key:['add','subtract','multiply','divide'].includes(e.op)?'('+e.args.map(formulaToText).join({add:'+',subtract:'-',multiply:'*',divide:'/'}[e.op])+')':e.op+'('+e.args.map(formulaToText).join(',')+')';}
