function catalog(world,built=[],roster=[]) {
  const actors=new Map();
  for(const a of Object.values(world?.actors || {})) {
    const notes=world.meta.native?.actors?.[a.id];
    actors.set(a.id,{id:a.id,name:a.name,kind:a.kind,aliases:notes?.aliases || [],skills:Object.keys(a.skills).map(id=>world.definitions.skills[id]).filter(Boolean).map(s=>({id:s.id,name:s.name,kind:s.kind}))});
  }
  for(const row of roster)if(!actors.has(row.id))actors.set(row.id,{id:row.id,name:row.name,kind:row.kind || 'ally',aliases:row.aliases || [],skills:[]});
  for(const row of built)actors.set(row.def.id,{id:row.def.id,name:row.def.name,kind:row.def.kind,aliases:row.record.aliases || [],skills:(row.record.skills || []).map(s=>({id:stableId(row.def.id+'-skill',s.name),name:s.name,kind:s.kind || (row.def.kind==='enemy'?'attack':undefined)}))});
  return [...actors.values()];
}
