const DEFAULTS = Object.freeze({staminaMax:100,actionStamina:10,restStamina:30,giftCost:10,startingMoney:0});
const num = (value,fallback,min,max) => Math.max(min,Math.min(max,Math.round(Number.isFinite(Number(value)) && value!==null && value!=='' ? Number(value) : fallback)));
