  schemaVersion:{enum:[1]},scope:object,profileRef:object,profile:object,actors:map(object),inventory:object,economy:object,combat:{enum:[null]},exploration:{enum:[null]},definitions:object,ledger:{type:'array',items:{},maxItems:10000},
  meta:{type:'object',required:['rulebook','social'],properties:{rulebook:{type:'object',required:['id','version','settings'],properties:{id:{enum:['romance','dating']},version:{enum:[1,2,3,4]},settings:object,instructions:string}},social:{type:'object',required:['relations','attempts','day','stamina','training','events','actionsCatalog'],properties:{relations:map(object),attempts:map(object),day:integer,actions:map(object),stamina:map(object),training:map(object),events:map(object),actionsCatalog:map(object),phase:integer,growth:map(object),trainingAttempts:map(object),schemes:map(object),incidents:map(object)}}}}
