    assert(b.stats.every(st=>bounded(a.raw?.[st.id],0,100))&&Object.keys(a.raw).length===b.stats.length,'RULEBOOK_INVALID',a.name+'의 룰북 능력치가 올바르지 않습니다.');
    assert(bounded(a.karma,-100,100)&&bounded(a.honor,0,100)&&['good','evil','neutral'].includes(a.alignment),'RULEBOOK_INVALID',a.name+'의 성향 정보가 올바르지 않습니다.');
    assert(Array.isArray(a.aliases) && a.aliases.every(v=>typeof v==='string') && a.resources && !Object.keys(a.resources).length,'RULEBOOK_INVALID','인물 별칭 또는 룰북 자원이 올바르지 않습니다.');
    const stamina=s.stamina[id];
